//! NAVM passthrough (M4.A4): navmeshes generated by the Creation Kit, imported unchanged.
//!
//! KitCraft cannot generate navmesh. The owner generates it in the Creation Kit for a cell
//! KitCraft built (fixture F22), and [`import_navmeshes`] copies every `NAVM` of that
//! CK-saved plugin into the KitCraft-built one: each record's bytes as the CK wrote them
//! (a compressed body is never recompressed, an unchanged record is re-emitted as read),
//! placed in the temporary children of the same cell in the target, where
//! [`crate::cells`] puts it (official style: `NAVM` first in the group). A target record
//! with the same FormID is replaced.
//!
//! Refused (`Error::Refused`), never repaired:
//!
//! - **different master lists.** The FormIDs inside a navmesh payload are opaque (no typed
//!   layout reads them) and stored relative to the source's masters, so they cannot be
//!   remapped: the target must have the source's masters in the same order, and no more
//!   (a longer list would move the source's own index onto a master of the target);
//! - a `NAVM` whose cell is not in the target (place or carry the cell first), or that sits
//!   anywhere but a cell's temporary children (the only place the corpus has them), or
//!   under a world's persistent cell (which has no temporary children in the corpus).
//!
//! Not imported: the `NAVI` navmesh info map and any other record the CK changed while
//! generating; F22 shows which records that is.

use crate::build::Placed;
use crate::cells::{self, group_type, CellPlace, Children, PlacementStyle};
use crate::index::PluginIndex;
use crate::model::{Entry, GroupHeader, Plugin, Record};
use crate::tes4::Tes4;
use crate::{DecodeLimits, Error, Result, Signature};

const NAVM: Signature = Signature::new(b"NAVM");
const CELL: Signature = Signature::new(b"CELL");

/// What [`import_navmeshes`] did.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct NavmeshImport {
    /// `NAVM` records added.
    pub inserted: usize,
    /// `NAVM` records that replaced one with the same FormID.
    pub replaced: usize,
    /// The cells (stored FormIDs) that received navmesh, in first-seen order.
    pub cells: Vec<u32>,
}

fn refused(reason: impl Into<String>) -> Error {
    Error::Refused {
        offset: 0,
        reason: reason.into(),
    }
}

fn names(header: &Record<'_>) -> Vec<String> {
    Tes4::new(header)
        .masters()
        .iter()
        .map(|m| m.name_lossy())
        .collect()
}

/// Refuse unless `target` has exactly `source`'s masters, in order (names compared without
/// case).
pub fn check_masters(source: &Record<'_>, target: &Record<'_>) -> Result<()> {
    let s = names(source);
    let t = names(target);
    let same = s.len() == t.len() && s.iter().zip(&t).all(|(a, b)| a.eq_ignore_ascii_case(b));
    if same {
        return Ok(());
    }
    Err(refused(format!(
        "navmesh import needs the same master list in both plugins: the source has [{}], \
         the target [{}]. FormIDs inside a navmesh payload are opaque and cannot be remapped",
        s.join(", "),
        t.join(", ")
    )))
}

/// Every `NAVM` of `source` with the cell whose temporary children hold it, in file order.
fn source_navmeshes<'p, 'a>(source: &'p Plugin<'a>) -> Result<Vec<(u32, &'p Record<'a>)>> {
    fn walk<'p, 'a>(
        entries: &'p [Entry<'a>],
        parent: Option<&GroupHeader>,
        out: &mut Vec<(Option<GroupHeader>, &'p Record<'a>)>,
    ) {
        for e in entries {
            match e {
                Entry::Group(g) => walk(g.children(), Some(&g.header), out),
                Entry::Record(r) if r.header.signature == NAVM => out.push((parent.copied(), r)),
                Entry::Record(_) => {}
            }
        }
    }
    let mut found = Vec::new();
    walk(source.entries(), None, &mut found);
    found
        .into_iter()
        .map(|(parent, r)| match parent {
            Some(g) if g.group_type == group_type::CELL_TEMPORARY => Ok((g.label_u32(), r)),
            _ => Err(refused(format!(
                "NAVM {:08X} is not in a cell's temporary children group, where every NAVM \
                 of the corpus is",
                r.header.form_id
            ))),
        })
        .collect()
}

/// Where cell `cell` sits in a plugin, from the group path that holds its `CELL` record
/// and, for an exterior cell, its `XCLC`.
fn place_from_path(path: &[GroupHeader], cell: &Record<'_>) -> Result<CellPlace> {
    let world = path
        .iter()
        .find(|g| g.group_type == group_type::WORLD_CHILDREN)
        .map(|g| g.label_u32());
    let Some(world) = world else {
        // An existing cell: the blocks it was found in, not recomputed.
        return Ok(CellPlace::Interior {
            labels: cells::interior_labels(path),
        });
    };
    if path
        .last()
        .is_some_and(|g| g.group_type == group_type::WORLD_CHILDREN)
    {
        return Ok(CellPlace::Persistent { world });
    }
    let decoded;
    let subs = match cell.subrecords() {
        Some(subs) => subs,
        None => {
            decoded = cell.decode(&DecodeLimits::default())?.unwrap_or_default();
            &decoded
        }
    };
    subs.iter()
        .find(|s| s.signature() == Signature::new(b"XCLC"))
        .and_then(|s| cells::Grid::from_xclc(s.data()))
        .map(|grid| CellPlace::Exterior { world, grid })
        .ok_or_else(|| refused("an exterior cell without an XCLC grid"))
}

/// The place of every `CELL` in `plugin`, by stored FormID.
fn cell_places(plugin: &Plugin<'_>) -> Result<Vec<(u32, CellPlace)>> {
    fn walk<'p, 'a>(
        entries: &'p [Entry<'a>],
        path: &mut Vec<GroupHeader>,
        out: &mut Vec<(Vec<GroupHeader>, &'p Record<'a>)>,
    ) {
        for e in entries {
            match e {
                Entry::Group(g) => {
                    path.push(g.header);
                    walk(g.children(), path, out);
                    path.pop();
                }
                Entry::Record(r) if r.header.signature == CELL => out.push((path.clone(), r)),
                Entry::Record(_) => {}
            }
        }
    }
    let mut found = Vec::new();
    walk(plugin.entries(), &mut Vec::new(), &mut found);
    found
        .into_iter()
        .map(|(path, r)| Ok((r.header.form_id, place_from_path(&path, r)?)))
        .collect()
}

fn placements<'a>(
    source: &Plugin<'a>,
    places: &[(u32, CellPlace)],
    style: &PlacementStyle,
) -> Result<Vec<(u32, Placed)>> {
    source_navmeshes(source)?
        .into_iter()
        .map(|(cell, r)| {
            let place = places
                .iter()
                .find(|(id, _)| *id == cell)
                .map(|(_, p)| *p)
                .ok_or_else(|| {
                    refused(format!(
                        "NAVM {:08X} belongs to cell {cell:08X}, which the target does not \
                         have: place or carry the cell first",
                        r.header.form_id
                    ))
                })?;
            let path = cells::cell_children_path(&place, cell, Children::Temporary, style)?;
            Ok((
                cell,
                Placed {
                    path,
                    record: r.clone().into_owned(),
                },
            ))
        })
        .collect()
}

/// Copy every `NAVM` of `source` (a CK-saved plugin) into `target`, unchanged, into the
/// temporary children of the same cell (see the module documentation).
pub fn import_navmeshes(
    source: &Plugin<'_>,
    target: &mut Plugin<'_>,
    style: &PlacementStyle,
) -> Result<NavmeshImport> {
    check_masters(source.header(), target.header())?;
    let places = cell_places(target)?;
    let mut report = NavmeshImport::default();
    for (cell, p) in placements(source, &places, style)? {
        match target.upsert_styled(&p.path, p.record, style)? {
            crate::build::Upsert::Inserted => report.inserted = report.inserted.saturating_add(1),
            crate::build::Upsert::Replaced | crate::build::Upsert::Moved => {
                report.replaced = report.replaced.saturating_add(1)
            }
        }
        if !report.cells.contains(&cell) {
            report.cells.push(cell);
        }
    }
    Ok(report)
}

/// The same import for a target streamed from disk ([`crate::build::upsert_file_to_path`]):
/// the [`Placed`] records, with each cell's place read from `target`'s index and, for an
/// exterior cell, from its record (`cell_record` reads one back, for example through
/// [`crate::index::read_indexed`]).
pub fn navmesh_placements(
    source: &Plugin<'_>,
    target: &PluginIndex,
    mut cell_record: impl FnMut(&crate::index::RecordLoc) -> Result<Record<'static>>,
    style: &PlacementStyle,
) -> Result<Vec<Placed>> {
    check_masters(source.header(), &target.header)?;
    let wanted: Vec<u32> = source_navmeshes(source)?.iter().map(|(c, _)| *c).collect();
    let mut places = Vec::new();
    for loc in target
        .records
        .iter()
        .filter(|r| r.signature == CELL && wanted.contains(&r.form_id))
    {
        let record = cell_record(loc)?;
        places.push((
            loc.form_id,
            cells::cell_place_in(target, loc, &record, &DecodeLimits::default())?,
        ));
    }
    Ok(placements(source, &places, style)?
        .into_iter()
        .map(|(_, p)| p)
        .collect())
}

#[cfg(test)]
#[allow(clippy::arithmetic_side_effects)]
mod tests {
    use super::{import_navmeshes, navmesh_placements, NavmeshImport};
    use crate::build::{set_masters, upsert_reader, HeaderSpec};
    use crate::cells::{self, CellPlace, Grid, Parent, PlacementStyle};
    use crate::driver::{roundtrip_bytes, RewriteOptions, RoundtripOptions};
    use crate::fixture::{self, compressed_record_stored, group, record, sub};
    use crate::index::{index_bytes, read_indexed, IndexOptions};
    use crate::{Entry, Error, Plugin, Record};
    use std::io::Cursor;

    fn parse_record(bytes: &[u8]) -> Record<'static> {
        crate::parse::parse_record(&mut crate::Reader::new(bytes, 0))
            .unwrap()
            .into_owned()
    }

    const CELL_ID: u32 = 0x0000_1234; // 4660: interior block 0, sub-block 6
    const WORLD: u32 = 0x0000_0050;
    const EXT_CELL: u32 = 0x0000_0060;

    /// A "CK-saved" plugin: masters [Starfield.esm], an interior cell override with a REFR
    /// and two compressed NAVMs, and an exterior cell with one NAVM.
    fn ck_plugin() -> Vec<u8> {
        let mut spec = HeaderSpec::new(vec![b"Starfield.esm".to_vec()]);
        spec.flags = 0;
        let mut plugin = Plugin::create(&spec);
        let style = PlacementStyle::OFFICIAL;
        let cell = parse_record(&record(b"CELL", 0, CELL_ID, &sub(b"EDID", b"c\0")));
        let refr = parse_record(&record(
            b"REFR",
            0,
            0x0100_0801,
            &sub(b"NAME", &[1, 0, 0, 0]),
        ));
        let navm = |id: u32, fill: u8| {
            let fields = [sub(b"NVNM", &[fill; 40]), sub(b"MNAM", &[])].concat();
            parse_record(&compressed_record_stored(b"NAVM", id, &fields))
        };
        let xclc = [1i32.to_le_bytes(), (-1i32).to_le_bytes(), [0u8; 4]].concat();
        let ext = parse_record(&record(b"CELL", 0, EXT_CELL, &sub(b"XCLC", &xclc)));
        let wrld = parse_record(&record(b"WRLD", 0, WORLD, &sub(b"EDID", b"w\0")));
        let interior = CellPlace::INTERIOR;
        let exterior = CellPlace::Exterior {
            world: WORLD,
            grid: Grid::new(1, -1),
        };
        let items = [
            (cell, Parent::CellAt(interior)),
            (
                refr,
                Parent::Cell {
                    place: interior,
                    cell: CELL_ID,
                },
            ),
            (
                navm(0x0100_0802, 7),
                Parent::Cell {
                    place: interior,
                    cell: CELL_ID,
                },
            ),
            (
                navm(0x0100_0803, 8),
                Parent::Cell {
                    place: interior,
                    cell: CELL_ID,
                },
            ),
            (wrld, Parent::None),
            (ext, Parent::CellAt(exterior)),
            (
                navm(0x0100_0804, 9),
                Parent::Cell {
                    place: exterior,
                    cell: EXT_CELL,
                },
            ),
        ];
        for (r, parent) in items {
            let path = cells::placement(&r.header, &parent, &style).unwrap();
            plugin.upsert_styled(&path, r, &style).unwrap();
        }
        plugin.to_bytes().unwrap()
    }

    /// The same plugin without its NAVMs (what KitCraft built before the CK session).
    fn without_navmeshes(bytes: &[u8]) -> Plugin<'static> {
        fn strip(entries: &mut Vec<Entry<'_>>) {
            entries.retain(|e| !matches!(e, Entry::Record(r) if r.header.signature.0 == *b"NAVM"));
            for e in entries.iter_mut() {
                if let Entry::Group(g) = e {
                    strip(g.children_mut());
                }
            }
        }
        let mut plugin = Plugin::parse(bytes).unwrap().into_owned();
        strip(plugin.entries_mut());
        // The emptied placeholder NAVM top group goes too.
        plugin
            .entries_mut()
            .retain(|e| !matches!(e, Entry::Group(g) if g.header.group_type == 0 && g.children().is_empty()));
        plugin
    }

    #[test]
    fn imported_navmeshes_are_the_ck_bytes_in_corpus_order() {
        let ck = ck_plugin();
        let source = Plugin::parse(&ck).unwrap();
        let mut target = without_navmeshes(&ck);
        let report = import_navmeshes(&source, &mut target, &PlacementStyle::OFFICIAL).unwrap();
        assert_eq!(
            report,
            NavmeshImport {
                inserted: 3,
                replaced: 0,
                cells: vec![CELL_ID, EXT_CELL],
            }
        );
        // The rebuilt plugin is the CK's, byte for byte: NAVMs first in their groups,
        // compressed bodies as written, the placeholder top group back.
        assert_eq!(target.to_bytes().unwrap(), ck);
        assert!(roundtrip_bytes(&ck, &RoundtripOptions::with_decode())
            .unwrap()
            .identical());
        // Importing again replaces in place.
        let again = import_navmeshes(&source, &mut target, &PlacementStyle::OFFICIAL).unwrap();
        assert_eq!((again.inserted, again.replaced), (0, 3));
        assert_eq!(target.to_bytes().unwrap(), ck);

        // Streaming: placements from the target's index, applied by upsert_reader.
        let base = without_navmeshes(&ck).to_bytes().unwrap();
        let index = index_bytes(&base, &IndexOptions::default()).unwrap();
        let mut file = Cursor::new(&base);
        let placed = navmesh_placements(
            &source,
            &index,
            |loc| read_indexed(&mut file, loc, None),
            &PlacementStyle::OFFICIAL,
        )
        .unwrap();
        assert_eq!(placed.len(), 3);
        let mut sink = Cursor::new(Vec::new());
        let report = upsert_reader(
            Cursor::new(&base),
            base.len() as u64,
            &RewriteOptions::default(),
            &mut sink,
            placed,
            |_| Ok(()),
        )
        .unwrap();
        if let Some(fix) = report.rewrite.hedr_fix {
            fix.apply(&mut sink).unwrap();
        }
        assert_eq!(sink.into_inner(), ck);
    }

    #[test]
    fn mismatched_masters_and_missing_cells_are_refused() {
        let ck = ck_plugin();
        let source = Plugin::parse(&ck).unwrap();
        let style = PlacementStyle::OFFICIAL;
        for masters in [
            vec![b"Other.esm".to_vec()],
            vec![b"Starfield.esm".to_vec(), b"Extra.esm".to_vec()],
            vec![],
        ] {
            let mut target = without_navmeshes(&ck);
            set_masters(target.header_mut(), &masters);
            let err = import_navmeshes(&source, &mut target, &style).unwrap_err();
            assert!(matches!(err, Error::Refused { .. }), "{err}");
            assert!(err.to_string().contains("master list"), "{err}");
        }
        // Same names in another case are the same masters.
        let mut target = without_navmeshes(&ck);
        set_masters(target.header_mut(), &[b"STARFIELD.ESM".to_vec()]);
        assert!(import_navmeshes(&source, &mut target, &style).is_ok());
        // A target without the cell.
        let mut empty = Plugin::create(&HeaderSpec::new(vec![b"Starfield.esm".to_vec()]));
        let err = import_navmeshes(&source, &mut empty, &style).unwrap_err();
        assert!(err.to_string().contains("00001234"), "{err}");
        assert!(empty.entries().is_empty());
        // A NAVM outside a temporary children group.
        let odd = fixture::plugin(&[group(
            b"NAVM",
            0,
            &compressed_record_stored(b"NAVM", 1, &sub(b"NVNM", &[0; 4])),
        )]);
        let odd = Plugin::parse(&odd).unwrap();
        let mut target = Plugin::create(&HeaderSpec::new(vec![
            b"Starfield.esm".to_vec(),
            b"Other.esm".to_vec(),
        ]));
        let err = import_navmeshes(&odd, &mut target, &style).unwrap_err();
        assert!(err.to_string().contains("temporary children"), "{err}");
    }
}
